<?php
namespace App\Services;use App\Models\{TaxClass,TaxRule};
class TaxEngine{public function calculate(int $amount,string $country,?string $taxClassCode=null,?string $region=null):array{$class=$taxClassCode?TaxClass::where('code',$taxClassCode)->where('is_active',true)->first():null;if(!$class)return ['tax_total'=>0,'rate_basis_points'=>0,'tax_class'=>null];$rule=$class->rules()->where('country_code',strtoupper($country))->where('is_active',true)->where(fn($q)=>$q->whereNull('region_code')->orWhere('region_code',$region))->orderByDesc('priority')->first();if(!$rule)return ['tax_total'=>0,'rate_basis_points'=>0,'tax_class'=>$class->code];$tax=(int)floor(($amount*(int)$rule->rate_basis_points+5000)/10000);return ['tax_total'=>$tax,'rate_basis_points'=>$rule->rate_basis_points,'tax_class'=>$class->code];}}
